    @staticmethod
    def _fetch_json(controller: Any, path: str, *, port: int = DEFAULT_PORT,
                    timeout: int = 15) -> dict[str, Any]:
        """Read one document from the store, or raise when it cannot be read.

        An unreadable store means the task has not been performed, so callers
        treat the raise as "absent" rather than as an evaluator fault.
        """
        if controller is None or not hasattr(controller, "run_python_script"):
            raise LookupError(f"{STATE_UNREADABLE} ({path}): no runtime controller")
        script = (
            "import urllib.request\n"
            "try:\n"
            f"    with urllib.request.urlopen('http://127.0.0.1:{int(port)}{path}',"
            f" timeout={int(timeout)}) as response:\n"
            "        print(response.read().decode('utf-8'))\n"
            "except Exception as exc:\n"
            "    print('OSOMNI_UNREADABLE', type(exc).__name__)\n"
        )
        result = controller.run_python_script(script, timeout=int(timeout) + 5)
        stdout = str(result.get("stdout") or result.get("output") or "")
        if "OSOMNI_UNREADABLE" in stdout or int(result.get("returncode", -1)) != 0:
            raise LookupError(f"{STATE_UNREADABLE} ({path})")
        try:
            payload = json.loads(stdout)
        except (TypeError, ValueError) as exc:
            raise LookupError(f"{STATE_UNREADABLE} ({path})") from exc
        if not isinstance(payload, Mapping):
            raise LookupError(f"{STATE_UNREADABLE} ({path})")
        return dict(payload)

